content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Collection Manager",
      "description": "Oversees waste collection operations and monitors performance."
    },
    {
      "name": "Route Schedule",
      "description": "Plan outlining upcoming collection routes and their timing.",
      "attributes": [
        "Collection Route"
      ]
    },
    {
      "name": "Collection Route",
      "description": "Defined path for waste collection including stops and assigned truck.",
      "attributes": [
        "Waste Truck",
        "Route Log",
        "Pickup Location"
      ]
    },
    {
      "name": "Waste Truck",
      "description": "Vehicle used for waste collection, linked to capacity, zone, and driver.",
      "attributes": [
        "Collection Zone",
        "Vehicle Capacity",
        "Driver",
        "Maintenance Records"
      ]
    },
    {
      "name": "Collection Zone",
      "description": "Geographical area covered by one or more collection routes."
    },
    {
      "name": "Vehicle Capacity",
      "description": "Maximum volume of waste a truck can carry on a route."
    },
    {
      "name": "Driver",
      "description": "Operates waste trucks and logs collection data during routes."
    },
    {
      "name": "Maintenance Records",
      "description": "Logs and documentation of maintenance performed on vehicles."
    },
    {
      "name": "Traffic Data",
      "description": "Information about current road and traffic conditions used for planning."
    },
    {
      "name": "Route Log",
      "description": "Record of collected waste volumes, stops, and incidents during a route."
    },
    {
      "name": "Pickup Location",
      "description": "Client site where waste is collected during a route."
    },
    {
      "name": "Maintenance Supervisor",
      "description": "Responsible for scheduling and overseeing vehicle maintenance."
    },
    {
      "name": "Client",
      "description": "Requests pickup services from the waste management company."
    },
    {
      "name": "Pickup Request",
      "description": "Client request for waste collection at a specific location.",
      "attributes": [
        "Pickup Location"
      ]
    },
    {
      "name": "Route Planner",
      "description": "Designs and adjusts collection routes for efficiency and coverage."
    },
    {
      "name": "Issue Report",
      "description": "Report created by drivers describing route issues or incidents."
    },
    {
      "name": "Recycling Coordinator",
      "description": "Manages sorting operations and the transfer of recyclable materials."
    },
    {
      "name": "Sorting Facility",
      "description": "Facility where collected waste is separated for recycling or disposal."
    },
    {
      "name": "Contamination Issue",
      "description": "Problem caused by mixing recyclable and non-recyclable materials."
    },
    {
      "name": "Material Transfer",
      "description": "Process of sending sorted materials to recycling partners."
    },
    {
      "name": "Partner Recycling Plant",
      "description": "External plant that receives and processes sorted recyclable materials."
    },
    {
      "name": "Preventive Maintenance",
      "description": "Scheduled servicing of vehicles to prevent breakdowns."
    }
  ]
}
```
